import{_ as e,H as B,f as t,i}from"./chunks/framework.BH2BK_3i.js";const r=JSON.parse('{"title":"21-网约车系统重构：如何用DDD重构网约车系统设计？","description":"","frontmatter":{},"headers":[{"level":2,"title":"DDD 的一般方法","slug":"ddd-的一般方法","link":"#ddd-的一般方法","children":[]},{"level":2,"title":"Udi DDD 重构设计","slug":"udi-ddd-重构设计","link":"#udi-ddd-重构设计","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"李智慧·高并发架构实战课/21-网约车系统重构：如何用DDD重构网约车系统设计？.md","filePath":"李智慧·高并发架构实战课/21-网约车系统重构：如何用DDD重构网约车系统设计？.md","lastUpdated":1795558450000}'),a={name:"李智慧·高并发架构实战课/21-网约车系统重构：如何用DDD重构网约车系统设计？.md"};function s(n,E,A,D,p,o){return B(),t("div",null,[...E[0]||(E[0]=[i('<h1 id="_21-网约车系统重构-如何用ddd重构网约车系统设计" tabindex="-1">21-网约车系统重构：如何用DDD重构网约车系统设计？ <a class="header-anchor" href="#_21-网约车系统重构-如何用ddd重构网约车系统设计" aria-label="Permalink to &quot;21-网约车系统重构：如何用DDD重构网约车系统设计？&quot;">​</a></h1><p>你好，我是李智慧。</p><p>软件开发是一个过程，这个过程中相关方对软件系统的认知会不断改变。当系统现状和大家的认知有严重冲突的时候，不重构系统就难以继续开发下去。此外，在持续的需求迭代过程中，代码本身会逐渐腐坏，变得僵硬、脆弱、难以维护，需求开发周期越来越长，bug 却越来越多，系统也必须要进行重构。</p><p>我们在前一篇讨论的 Udi 网约车系统经过了几年的快速发展，随着业务越来越复杂，功能模块越来越多，开发团队越来越庞大，整个系统也越来越笨拙、难以维护。以前两三天就能开发完成的新功能，现在要几个星期，开发人员多了，工作效率却下降了。</p><p>Udi 使用微服务架构，开始的时候业务比较简单，几个微服务就可以搞定。后面随着功能越来越多，微服务也越来越多，微服务之间的依赖关系也变得越来越复杂，常常要开发一个小功能，却需要在好几个微服务中进行修改。后来开发人员为了避免这种复杂性，倾向于把所有功能都写在一个微服务里，结果整个系统架构又开始退回到单体架构。</p><p>基于以上原因，我们准备对 Udi 进行一次重构，核心就是要解决微服务设计的混乱，梳理、重构出更加清晰的微服务边界和微服务之间的依赖关系。我们准备使用 DDD，即领域驱动设计的方法进行这次重构。</p><p>那么，领域驱动设计的核心思想是什么？设计的一般方法是什么？如何将这些方法应用到 Udi的重构过程中？这些就是我们今天要解决的主要问题。</p><h2 id="ddd-的一般方法" tabindex="-1">DDD 的一般方法 <a class="header-anchor" href="#ddd-的一般方法" aria-label="Permalink to &quot;DDD 的一般方法&quot;">​</a></h2><p>领域是一个组织所做的事情以及其包含的一切，通俗地说，就是组织的业务范围和做事方式，也是软件开发的目标范围。比如对于淘宝这样一个以电子商务为主要业务的组织，C2C 电子商务就是它的领域。领域驱动设计就是从领域出发，分析领域内模型及其关系，进而设计软件系统的方法。</p><p>但是如果我们说要对 C2C 电子商务这个领域进行建模设计，那么这个范围就太大了，不知道该如何下手。所以通常的做法是把整个领域拆分成多个子域，比如用户、商品、订单、库存、物流、发票等。强相关的多个子域组成一个限界上下文，它是对业务领域范围的描述，对于系统实现而言，限界上下文相当于是一个子系统或者一个模块。限界上下文和子域共同组成组织的领域，如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/1.png" alt=""></a></p><p>不同的限界上下文，也就是不同的子系统或者模块之间会有各种的交互合作。如何设计这些交互合作呢？DDD 使用上下文映射图来完成，如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/2.png" alt=""></a></p><p>在 DDD 中，领域模型对象也被称为实体。先通过业务分析，识别出实体对象，然后通过相关的业务逻辑，设计实体的属性和方法。而限界上下文和上下文映射图则是微服务设计的关键，通常在实践中，限界上下文被设计为微服务，而上下文映射图就是微服务之间的依赖关系。具体设计过程如下图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/3.png" alt=""></a></p><p>首先，领域专家和团队一起讨论分析业务领域，确认业务期望，将业务分解成若干个业务场景。然后，针对每个场景画 UML 活动图，活动图中包含泳道，通过高内聚原则对功能逻辑不断调整，使功能和泳道之间的归属关系变得更加清晰合理。这些泳道最终就是限界上下文，泳道内的功能就是将来微服务的功能边界，泳道之间的调用流程关系，就是将来微服务之间的依赖关系，即上下文映射图。</p><p>但是，这个状态的泳道还不能直接转化成限界上下文。有些限界上下文可能会很大，有些依赖关系可能会比较强。而一个限界上下文不应该超过一个团队的职责范围，因为根据康威定律：组织架构决定系统架构，两个团队维护一个微服务，必然会将这个微服务搞成事实上的两个微服务。所以，我们还需要根据团队特性、过往的工作职责、技能经验，重新对泳道图进行调整，使其符合团队的职责划分，这时候才得到限界上下文。</p><p>在这个限界上下文基础上，考虑技术框架、非功能需求、服务重用性等因素，进一步进行调整，就得到最终的限界上下文设计，形成我们的微服务架构设计。</p><p>我们将遵循上述 DDD 方法过程对 Udi 微服务进行重新分析设计，并进行系统重构。</p><h2 id="udi-ddd-重构设计" tabindex="-1">Udi DDD 重构设计 <a class="header-anchor" href="#udi-ddd-重构设计" aria-label="Permalink to &quot;Udi DDD 重构设计&quot;">​</a></h2><p>首先分析我们的业务领域，通过头脑 / 事件风暴的形式，收集领域内的所有事件 / 命令，并识别事件 / 命令的发起方即对应的实体。最后识别出来的实体以及相关活动如下表：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/4.png" alt=""></a></p><p>基于核心实体模型，绘制实体关系图，如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/5.png" alt=""></a></p><p>在实体间关系明确且完整的前提下，我们就可以针对各个业务场景，绘制场景活动图。活动图比较多，这里仅用拼车场景作为示例，如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/6.png" alt=""></a></p><p>依据各种重要场景的活动图，参考团队职责范围，结合微服务重用性考虑及非功能需求，产生限界上下文如下表：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/7.png" alt=""></a></p><p>针对每个限界上下文进一步设计其内部的聚合、聚合根、实体、值对象、功能边界。以订单限界上下文为例：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/8.png" alt=""></a></p><p>上述订单实体的属性和功能如下表：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/9.png" alt=""></a></p><p>最后，在实现层面，设计对应的微服务架构如下图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/21-%25E7%25BD%2591%25E7%25BA%25A6%25E8%25BD%25A6%25E7%25B3%25BB%25E7%25BB%259F%25E9%2587%258D%25E6%259E%2584/10.png" alt=""></a></p><p>这是一个基于领域模型的分层架构，最下层为聚合根对象，组合实体与值对象，完成核心业务逻辑处理。上面一层为领域服务层，主要调用聚合根对象完成订单子域的业务，根据业务情况，也会在这一层和其他微服务通信，完成更复杂的、超出当前实体职责的业务，所以这一层也是一个聚合层。</p><p>再上面一层是应用服务层，将实体的功能封装成各种服务，供各种应用场景调用。而最上面是一个接口层，提供微服务调用接口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>领域驱动设计很多时候雷声大，雨点小，说起来各种术语满天飞，真正开发实践的时候又无从下手。这节的案例来自一个真实落地的 DDD 重构设计文档，你可以参考这个文档，按图索骥，应用到自己的开发实践中。</p><p>既然说到“按图索骥”，那我认为也有必要在这一节的最后，帮你画一个更有概括性的 DDD 重构路线图，我们把使用 DDD 进行系统重构的过程分为以下六步：</p><ol><li><p>讨论当前系统存在的问题，发现问题背后的根源。比如：架构与代码混乱，需求迭代困难，部署麻烦，bug 率逐渐升高；微服务边界不清晰，调用依赖关系复杂，团队职责混乱。</p></li><li><p>针对问题分析具体原因。比如：微服务 A 太庞大，微服务 B 和 C 职责不清，团队内业务理解不一致，内部代码设计不良，硬编码和耦合太多。</p></li><li><p>重新梳理业务流程，明确业务术语，进行 DDD 战略设计，具体又可以分为三步。a. 进行头脑风暴，分析业务现状和期望，构建领域语言；</p></li></ol><ul><li><p>b. 画泳道活动图、结合团队特性设计限界上下文；</p></li><li><p>c. 根据架构方案和非功能需求确定微服务设计。</p></li></ul><ol start="4"><li><p>针对当前系统实现和 DDD 设计不匹配的地方，设计微服务重构方案。比如：哪些微服务需要重新开发，哪些微服务的功能需要从 A 调整到 B，哪些微服务需要分拆。</p></li><li><p>DDD 技术验证。针对比较重要、问题比较多的微服务进行重构打样，设计聚合根、实体、值对象，重构关键代码，验证设计是否合理以及团队能否驾驭 DDD。</p></li><li><p>任务分解与持续重构。在尽量不影响业务迭代的前提下，按照重构方案，将重构开发和业务迭代有机融合。</p></li></ol><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你认为 DDD 最大的价值是什么？如何才能成功落地 DDD？</p><p>欢迎在评论区分享你的思考，我们共同进步。</p><ul><li>【编辑温馨提示】4 月 10 日 12 点前，提交期中测试作业，有机会获得老师精心准备的奖励哦~</li></ul>',46)])])}const h=e(a,[["render",s]]);export{r as __pageData,h as default};
